def main():
    rows = []
    known = {r[0] for r in ROWS}
    for sid, title, deps, lane, paths, acceptance, excluded in ROWS:
        assert set(deps) <= known
        rows.append(dict(id=sid, title=title, dependencies=deps, lane=lane, paths=paths,
                         acceptance=acceptance, excluded=excluded,
                         state='PLANNED_NOT_IMPLEMENTED', lease='NOT_GRANTED',
                         code_base='ad814c232ee24109639c1d52239cbeec6f4a3e92',
                         branch=f'codex/syson-{sid.lower()}',
                         review_budget='One behavior family; aim for <=400 changed handwritten production lines and <=900 authored lines including tests. Split before exceeding this; separate generated tables and runtime receipts.',
                         execution_gates=['Existing held leases must be explicitly reconciled before overlapping work.', 'No new compiler/display entitlement; retain the shared allocation protocol.', 'New dependencies, upstream builds/services and credential changes retain exact action review.']))
    by_id = {r['id']:r for r in rows}
    visiting, done = set(), set()
    def visit(sid):
        assert sid not in visiting, f'Cycle at {sid}'
        if sid in done:
            return
        visiting.add(sid)
        for dep in by_id[sid]['dependencies']:
            visit(dep)
        visiting.remove(sid)
        done.add(sid)
    for sid in by_id:
        visit(sid)
    # Broad area coverage is a traceability index, never a completeness claim.
    coverage = {
      'DOMAIN-NAME':['F44'], 'DOMAIN-ID':['F45'], 'DOMAIN-QUERY':['F01','F02','F03','F04','F46'],
      'EDITOR-ROTATE':['F19'], 'EDITOR-GEOMETRY':['F15'], 'MIGRATION-ID':['F28'],
      'MODEL':['F05','F06','F07','F33','F46','F47'], 'PARSER':['F08','F09','F10','F11','F12','F13','F14'],
      'UI':['F19','F30','F36','F37'], 'LAYOUT':['F15','F16','F17','F18','F19'],
      'API':['F20','F21','F22','F23','F24'], 'DB':['F25','F26','F27'],
      'RECOVERY':['F31','F32'], 'HISTORY':['F29','F30'], 'ACCESSIBILITY':['F36'],
      'EXPORT':['F33','F34','F35'], 'EXTENSIONS':['F38'], 'DEPS':['F39','F40','F43'],
    }
    manifest=dict(schema_version=1, status='PROPOSED_PR_HANDOFFS_NOT_A_REPLACEMENT_BACKLOG',
                  inventory_complete=False, full_parity_claimed=False, units=rows, area_coverage=coverage,
                  residual_policy='After each finite behavior/rule/classifier family, enumerate the next source-backed sibling family in a new PR. These 47 units start all 18 areas but do not close the incomplete baseline inventory or all 735 grammar / 848 AST obligations.')
    (OUT/'future-prs.json').write_text(json.dumps(manifest,indent=2)+'\n')
    briefs=OUT/'briefs'
    briefs.mkdir(exist_ok=True)
    for r in rows:
        deps=', '.join(r['dependencies']) or 'None among these future units; source/lease/execution prerequisites still apply.'
        text=f"# {r['id']}: {r['title']}\n\nPlanned implementation PR; no code has been implemented or tested by this brief.\n\n- Branch: `{r['branch']}`\n- Proposed lane: {r['lane']} (not an assignment or lease)\n- Future prerequisites: {deps}\n- Source base: `{r['code_base']}`; recheck the actual integration head and source contract before work.\n\n## Scope and acceptance\n\n{r['acceptance']}\n\n## Writable scope to request\n\n"+'\n'.join(f'- `{p}`' for p in r['paths'])+f"\n\nNew crate manifests, module exports and cross-crate API wiring are integrator-owned. Request an exact API/module registration before depending on it; competing workers must not edit a common lib.rs, Cargo.toml, Cargo.lock or backlog. New paths are proposals and need an admitted source/lease boundary.\n\n## Review size\n\n{r['review_budget']} The 7,728-line existing factory candidate is a separately isolated historical review exception, not a size template.\n\n## Boundaries\n\n{r['excluded']}\n\n"+'\n'.join('- '+g for g in r['execution_gates'])+"\n\nRecord pinned upstream source, exact implementation/harness revisions, positive/negative cases, original failures, actual commands/results and independent review. Mark unrun checks unrun. A local pass does not establish upstream or whole-area parity.\n"
        (briefs/f"{r['id']}.md").write_text(text)
    print(json.dumps(dict(units=len(rows), acyclic=True, permanent_areas=len(coverage), initial_independent_units=[r['id'] for r in rows if not r['dependencies']]),indent=2))

if __name__=='__main__':
    main()
